    {
      "symbol": "⚖️",
      "tooltip": "Accountability is like a balance scale, it weighs the immediate rights of individuals against the unchecked speed of corporate deployment."
    },
    {
      "symbol": "🔍",
      "tooltip": "Independent oversight is like a magnifying glass, it reveals the specific, hidden biases currently embedded in proprietary algorithms."
    }
  ],
  "claim_sketches": [
    {
      "claim": "We must stop treating AI as an inevitable, autonomous force of nature and start treating it as a product that requires the same rigorous, independent, and mandatory oversight we demand of any other industry that impacts public safety.",
      "targets": []
    },
    {
      "claim": "The 'existential risk' narrative is a tactical distraction from documented, present-day harms.",
      "targets": []
    },
    {
      "claim": "Industry self-regulation remains a conflict of interest, not a safety strategy.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Documented, present-day harms are more policy-relevant than hypothetical future risks.",
      "if_wrong": "If AI poses a near-term existential threat regardless of current utility, my focus on immediate regulation would be insufficient, necessitating a precautionary pause rather than iterative oversight."
